#import "SXHomeController.h"
#import "SXStore.h"
#import "SXUI.h"
#import "SXMarketController.h"
#import "SXResearchController.h"
@interface SXHomeController ()
@property(nonatomic,strong) NSArray *recent;
@end
@implementation SXHomeController
- (instancetype)init {return [super initWithStyle:UITableViewStyleInsetGrouped];}
- (void)viewDidLoad {[super viewDidLoad];self.title=@"拾序";self.tableView.estimatedRowHeight=80;self.tableView.rowHeight=UITableViewAutomaticDimension;self.refreshControl=[UIRefreshControl new];[self.refreshControl addTarget:self action:@selector(refresh) forControlEvents:UIControlEventValueChanged];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc] initWithImage:[UIImage systemImageNamed:@"plus"] style:UIBarButtonItemStylePlain target:self action:@selector(newResearch)];self.navigationItem.rightBarButtonItem.accessibilityLabel=@"新的研究";[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(changed) name:SXStoreDidChangeNotification object:nil];[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(changed) name:SXQuotesDidChangeNotification object:nil];[self changed];}
- (void)viewWillAppear:(BOOL)animated {[super viewWillAppear:animated];[self changed];[self refresh];}
- (void)dealloc {[NSNotificationCenter.defaultCenter removeObserver:self];}
- (void)changed {self.recent=[[[SXStore sharedStore].runs sortedArrayUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){double av=SXFiniteNumber(a[@"createdAt"])?[a[@"createdAt"] doubleValue]:0,bv=SXFiniteNumber(b[@"createdAt"])?[b[@"createdAt"] doubleValue]:0;return av>bv?NSOrderedAscending:av<bv?NSOrderedDescending:NSOrderedSame;}] subarrayWithRange:NSMakeRange(0,MIN(4,[SXStore sharedStore].runs.count))];[self.tableView reloadData];}
- (void)refresh {NSMutableArray *codes=[NSMutableArray new];for(NSDictionary *position in [SXStore sharedStore].account[@"positions"])if([position[@"code"] isKindOfClass:NSString.class])[codes addObject:position[@"code"]];[[SXStore sharedStore] refreshQuotesForCodes:codes completion:^{[self.refreshControl endRefreshing];}];}
- (void)newResearch {self.tabBarController.selectedIndex=2;UINavigationController *nav=self.tabBarController.selectedViewController;[(SXResearchController *)nav.viewControllers.firstObject openSetupForCode:@"AMD"];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)tableView {return 3;}
- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section {return section==0?2:section==1?MAX(1,self.recent.count):3;}
- (NSString *)tableView:(UITableView *)tableView titleForHeaderInSection:(NSInteger)section {return @[@"我的資產",@"接續上次研究",@"快速開始"][section];}
- (NSString *)tableView:(UITableView *)tableView titleForFooterInSection:(NSInteger)section {return section==0?@"現金加持股市值，美元與台幣獨立計算。下拉可更新行情。":nil;}
- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)indexPath {
 UITableViewCell *cell=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];cell.textLabel.font=[UIFont preferredFontForTextStyle:UIFontTextStyleHeadline];cell.textLabel.adjustsFontForContentSizeCategory=YES;cell.detailTextLabel.adjustsFontForContentSizeCategory=YES;cell.detailTextLabel.numberOfLines=0;cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;SXStore *store=[SXStore sharedStore];
 if(indexPath.section==0){NSString *currency=indexPath.row==0?@"USD":@"TWD";double cash=0,value=0;BOOL complete=YES,stale=NO;NSUInteger count=0,priced=0;for(NSDictionary *entry in store.account[@"cash"])if([entry[@"currency"] isEqual:currency]){if(SXFiniteNumber(entry[@"amount"]))cash+=[entry[@"amount"] doubleValue];else complete=NO;}for(NSDictionary *position in store.account[@"positions"])if([position[@"currency"] isEqual:currency]){count++;NSDictionary *quote=store.quotes[position[@"code"]];if(SXFiniteNumber(quote[@"price"])&&[quote[@"price"] doubleValue]>0&&SXFiniteNumber(position[@"quantity"])&&[position[@"quantity"] doubleValue]>0){value+=[quote[@"price"] doubleValue]*[position[@"quantity"] doubleValue];priced++;}else complete=NO;if([store.quoteErrors containsObject:position[@"code"]])stale=YES;}
  cell.textLabel.text=[NSString stringWithFormat:@"%@  %@",currency,complete?SXMoney(@(cash+value),currency):@"等待完整報價"];cell.detailTextLabel.text=[NSString stringWithFormat:@"現金 %@ · 持股 %@\n報價 %lu / %lu 檔%@",SXMoney(@(cash),currency),complete?SXMoney(@(value),currency):@"—",(unsigned long)priced,(unsigned long)count,stale?@" · 更新暫停，採上次資料":@""];cell.imageView.image=[UIImage systemImageNamed:currency==@"USD"?@"dollarsign.circle":@"banknote"];
 }else if(indexPath.section==1){if(!self.recent.count){cell.textLabel.text=@"開始第一份研究";cell.detailTextLabel.text=@"選擇股票與期間，完成後可在研究庫回看。";cell.imageView.image=[UIImage systemImageNamed:@"sparkles"];}else{NSDictionary *run=self.recent[indexPath.row];NSString *status=[run[@"status"] isEqual:@"running"]?@"分析進行中":[run[@"status"] isEqual:@"failed"]?@"分析未完成":[run[@"status"] isEqual:@"completed"]?@"查看結果":@"查看紀錄";cell.textLabel.text=[NSString stringWithFormat:@"%@ · %@",run[@"code"],status];cell.detailTextLabel.text=[NSString stringWithFormat:@"%@ · %@",[run[@"horizon"] isEqual:@126]?@"半年":[NSString stringWithFormat:@"%@ 日",run[@"horizon"]?:@"—"],SXDateLabel(run[@"createdAt"])];cell.imageView.image=[UIImage systemImageNamed:[run[@"status"] isEqual:@"running"]?@"hourglass":@"doc.text"];}}
 else {cell.textLabel.text=@[@"探索市場與自選",@"開啟研究庫",@"登錄資金與持股"][indexPath.row];cell.detailTextLabel.text=@[@"真實行情、公司資料、情報與研究筆記",@"搜尋、篩選與釘選原始分析",@"查看成本、市值與資產分布"][indexPath.row];cell.imageView.image=[UIImage systemImageNamed:@[@"chart.xyaxis.line",@"books.vertical",@"chart.pie"][indexPath.row]];}return cell;
}
- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)indexPath {[tableView deselectRowAtIndexPath:indexPath animated:YES];if(indexPath.section==0){[[SXStore sharedStore] setProfileValue:indexPath.row==0?@"USD":@"TWD" forKey:@"account.currency"];self.tabBarController.selectedIndex=3;}else if(indexPath.section==1&&self.recent.count){self.tabBarController.selectedIndex=2;UINavigationController *nav=self.tabBarController.selectedViewController;[(SXResearchController *)nav.viewControllers.firstObject openRun:self.recent[indexPath.row]];}else if(indexPath.section==1)[self newResearch];else self.tabBarController.selectedIndex=indexPath.row==0?1:indexPath.row==1?2:3;}
@end
